package hk.jimmy.wearmemory;
import android.app.*; import android.content.*; import android.os.*; import android.graphics.Color; import android.view.*; import android.widget.*; import java.io.*; import java.text.*; import java.util.*;
public class ScheduleReceiver extends BroadcastReceiver {
static void schedule(Context c){android.content.SharedPreferences p=c.getSharedPreferences("settings",0);AlarmManager a=c.getSystemService(AlarmManager.class);for(String k:new String[]{"night","morning"}){Calendar cal=Calendar.getInstance();int m=p.getInt(k,k.equals("night")?60:480);cal.set(Calendar.HOUR_OF_DAY,m/60);cal.set(Calendar.MINUTE,m%60);cal.set(Calendar.SECOND,0);if(cal.getTimeInMillis()<=System.currentTimeMillis())cal.add(Calendar.DAY_OF_YEAR,1);if(k.equals("night")){android.app.job.JobScheduler js=c.getSystemService(android.app.job.JobScheduler.class);js.schedule(new android.app.job.JobInfo.Builder(100,new ComponentName(c,AnalysisService.class)).setMinimumLatency(cal.getTimeInMillis()-System.currentTimeMillis()).setRequiresCharging(p.getBoolean("charging",true)).setPersisted(true).build());continue;}PendingIntent pi=PendingIntent.getBroadcast(c,k.equals("night")?1:2,new Intent(c,ScheduleReceiver.class).setAction("hk.jimmy.wearmemory."+k.toUpperCase(Locale.US)),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,cal.getTimeInMillis(),pi);}}
public void onReceive(Context c,Intent i){schedule(c);if(i.getAction().endsWith("MORNING")){Ui.notify(c,30,"你的每日回顧",Ui.read(new File(c.getFilesDir(),"status.txt")));}else if(i.getAction().endsWith("NIGHT")){try{c.startForegroundService(new Intent(c,AnalysisService.class).putExtra("scheduled",true));}catch(Exception e){Ui.notify(c,31,"夜間分析待開始","點按開啟 App 開始本機分析");}}}}
